#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int a, b, c, x, y, z;
    cin >> a >> b >> c >> x >> y >> z;

    int surplus = max(0, a - x) / 2
                + max(0, b - y) / 2
                + max(0, c - z) / 2;

    int deficit = max(0, x - a)
                + max(0, y - b)
                + max(0, z - c);

    cout << (surplus >= deficit ? "Yes" : "No");
    return 0;
}

